 "content": "def transform(grid):
    """Copy a lone occupied panel into the immediately-right panel, mirrored."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    hlines = [r for r in range(h) if all(v == 8 for v in grid[r])]
    vlines = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    def intervals(size, dividers):
        result = []
        start = 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < size:
            result.append((start, size))
        return result

    row_panels = intervals(h, hlines)
    col_panels = intervals(w, vlines)
    for r0, r1 in row_panels:
        occupied = []
        for c0, c1 in col_panels:
            occupied.append(any(grid[r][c] != 0 and grid[r][c] != 8
                                for r in range(r0, r1) for c in range(c0, c1)))
        # A lone panel pattern is paired with its horizontal reflection to the right.
        if sum(occupied) != 1:
            continue
        src = occupied.index(True)
        if src + 1 >= len(col_panels):
            continue
        c0, c1 = col_panels[src]
        d0, d1 = col_panels[src + 1]
        width = min(c1 - c0, d1 - d0)
        height = min(r1 - r0, r1 - r0)
        for dr in range(height):
            for dc in range(width):
                value = grid[r0 + dr][c1 - 1 - dc]
                if value not in (0, 8):
                    out[r0 + dr][d0 + dc] = value
    return out
